const INSTAGRAM_COOKIE_URLS = [
  'https://www.instagram.com/',
  'https://instagram.com/',
];

export const INSTAGRAM_LOGIN_COOKIE_NAMES = ['ds_user_id', 'sessionid'];

function isInstagramCookieDomain(domain = '') {
  const normalizedDomain = String(domain).replace(/^\./, '').toLowerCase();
  return normalizedDomain === 'instagram.com' || normalizedDomain.endsWith('.instagram.com');
}

export function isInstagramLoginCookie(cookie) {
  return !!(
    cookie &&
    isInstagramCookieDomain(cookie.domain) &&
    INSTAGRAM_LOGIN_COOKIE_NAMES.includes(cookie.name)
  );
}

async function getCookieByUrl(name) {
  for (let i = 0; i < INSTAGRAM_COOKIE_URLS.length; i++) {
    const cookie = await chrome.cookies.get({ url: INSTAGRAM_COOKIE_URLS[i], name });
    if (cookie && cookie.value) return cookie.value;
  }
  return '';
}

async function getCookieByDomain(name) {
  const domains = ['instagram.com', '.instagram.com'];
  const seenCookieKeys = new Set();

  for (let i = 0; i < domains.length; i++) {
    const cookies = await chrome.cookies.getAll({ domain: domains[i], name });
    for (let j = 0; j < cookies.length; j++) {
      const cookie = cookies[j];
      const key = `${cookie.domain}|${cookie.path}|${cookie.name}`;
      if (seenCookieKeys.has(key)) continue;
      seenCookieKeys.add(key);
      if (isInstagramLoginCookie(cookie) && cookie.value) return cookie.value;
    }
  }

  return '';
}

export async function getInstagramCookies() {
  try {
    for (let i = 0; i < INSTAGRAM_LOGIN_COOKIE_NAMES.length; i++) {
      const cookieName = INSTAGRAM_LOGIN_COOKIE_NAMES[i];
      const cookieByUrl = await getCookieByUrl(cookieName);
      if (cookieByUrl) return cookieByUrl;

      const cookieByDomain = await getCookieByDomain(cookieName);
      if (cookieByDomain) return cookieByDomain;
    }
  } catch (error) {
    console.warn('Failed to read Instagram login cookies:', error);
  }

  return '';
}


export function isInstagramUrl(url) {
  return url.startsWith("https://www.instagram.com/") || url.startsWith("https://instagram.com/")
}

function extractPostCode(url) {
  // 兼容 /p/CODE、/reel/CODE、/reels/CODE、/tv/CODE，有无尾部斜杠均可，忽略 query string
  const match = /\/(?:p|reels?|tv)\/([A-Za-z0-9_-]+)/i.exec(url);
  return match && match[1] ? match[1] : "";
}


export function validatePostUrl(inputUrl) {
  let result = {
    error: '',
    postCode: ''
  }
  if (inputUrl == "") {
    result.error = "Instagram post url can't be empty"
    return result
  }

  if (!isInstagramUrl(inputUrl)) { // 输入的不是ins post url
    result.error = "This is not IG Post URL"
  } else {
    result.postCode = extractPostCode(inputUrl)
  }

  return result
}



