import '../util/alilog';
import {
  aliLog,
  getInstallTime,
  getUserProfileId,
  getUUID,
  setGeneralParamsOnInstall,
} from '../util/alilog';
import { SYNC_LOGIN_STATUS } from '../common/constants';
import { getInstagramCookies, isInstagramLoginCookie } from '../util/utils';
import { stgSetInstagramLoginInfo } from '../common/storage';

// 初次安装直接打开扩展的options页面
chrome.runtime.onInstalled.addListener(async (details) => {
  if (details.reason === 'install') {
    chrome.runtime.openOptionsPage();

    await findUserProfileId();
    await setGeneralParamsOnInstall();
    aliLog('2j0010');
  }
});

//接收消息
async function syncInstagramLoginStatus() {
  const value = await getInstagramCookies();
  await stgSetInstagramLoginInfo({ cookie: value, updatedAt: Date.now() });
  return value;
}

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg && typeof msg === 'object' && 'action' in msg) {
    switch (msg.action) {
      case 'onmessage':
        console.log('接收消息');
        break;
    }
  } else if (msg && msg.code === SYNC_LOGIN_STATUS) {
    syncInstagramLoginStatus()
      .then((value) => {
        sendResponse({ cookie: value });
      })
      .catch((error) => {
        console.warn('Failed to sync Instagram login status:', error);
        sendResponse({ cookie: '' });
      });
    return true;
  } else if (msg?.code === 'alilog_send') {
    // 阿里日志
    aliLog(msg.event_type, msg.event_data || {});
  }
  return false;
});

chrome.cookies.onChanged.addListener(async ({ cookie, removed }) => {
  if (!isInstagramLoginCookie(cookie)) return;

  const value = removed ? await getInstagramCookies() : (cookie.value || await getInstagramCookies());
  await stgSetInstagramLoginInfo({ cookie: value, updatedAt: Date.now() });
});



async function getClientVersion() {
  let options = chrome.runtime.getManifest();
  return options.version;
}

//fetch请求
function fetchRequest(url, callback) {
  fetch(url, { method: 'GET' })
    .then((res) => {
      return res.json();
    })
    .then((result) => {
      if (callback) callback(result);
    });
}

async function findUserProfileId() {
  try {
    await fetch('https://www.instagram.com/')
      .then((res) => res.text())
      .then(async (data) => {
        const marr = data.match(/username\\":\\"(.*)\\",\\"badge_count\\"/g);
        if (marr?.length === 1) {
          const str = marr[0].match(/username\\":\\"(.*)\\",\\"badge_count\\"/);
          if (str[1]) {
            await chrome.storage.local.set({ userProfileId: str[1] });
          }
        }
      })
      .catch(console.error);
  } catch (error) {
    console.error(error);
  }
}
